BEGIN TRANSACTION;

CREATE TABLE IF NOT EXISTS provinces (
    province_code TEXT PRIMARY KEY,
    country_code TEXT NOT NULL DEFAULT 'ZM',
    province_name TEXT NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS authority_master (
    authority_id TEXT PRIMARY KEY,
    country_code TEXT NOT NULL,
    province_code TEXT NOT NULL,
    legacy_authority_code TEXT NOT NULL UNIQUE,
    display_code TEXT NOT NULL,
    authority_ref TEXT NOT NULL UNIQUE,
    authority_name TEXT NOT NULL UNIQUE,
    official_name TEXT NOT NULL UNIQUE,
    authority_type TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'active',
    valid_from DATE,
    valid_to DATE,
    FOREIGN KEY (province_code) REFERENCES provinces(province_code)
);

DELETE FROM authority_master;
DELETE FROM provinces;
DELETE FROM authorities;
DELETE FROM authority_codes;



DROP VIEW IF EXISTS authority_lookup;
CREATE VIEW authority_lookup AS
SELECT am.authority_id, am.country_code, am.province_code, p.province_name, am.legacy_authority_code, am.display_code, am.authority_ref, am.authority_name, am.official_name, am.authority_type, am.status, am.valid_from, am.valid_to
FROM authority_master am
JOIN provinces p ON p.province_code = am.province_code;

COMMIT;
